import * as crypto from 'node:crypto';
function main(): void {
  const c: any = crypto;
  for (const curve of ['prime256v1', 'secp384r1', 'secp521r1']) {
    const e: any = c.createECDH(curve);
    e.setPrivateKey(Buffer.from('0102030405060708090a0b0c0d0e0f10111213141516171819', 'hex').subarray(0, 24));
    const pub: any = e.getPublicKey();
    const comp: any = c.ECDH.convertKey(pub, curve, undefined, undefined, 'compressed');
    const back: any = c.ECDH.convertKey(comp, curve, undefined, 'hex');
    console.log(curve, comp.length, comp.toString('hex') === e.getPublicKey(undefined, 'compressed').toString('hex'), back === pub.toString('hex'),
      c.ECDH.convertKey(pub, curve, undefined, 'hex', 'hybrid') === e.getPublicKey('hex', 'hybrid'));
  }
  const g: any = c.ECDH.convertKey('0279be667ef9dcbbac55a06295ce870b07029bfcdb2dce28d959f2815b16f81798', 'secp256k1', 'hex', 'hex');
  console.log(g, c.ECDH.convertKey(g, 'secp256k1', 'hex', 'hex', 'hybrid'), c.ECDH.convertKey(g, 'secp256k1', 'hex', 'hex', 'compressed'));
  for (const args of [[Buffer.alloc(33, 5), 'prime256v1'], [Buffer.alloc(33, 5), 'nope'], [1, 'prime256v1']]) {
    try { c.ECDH.convertKey(...(args as any)); } catch (err: any) { console.log(err.code, err.message); }
  }
}
